@st.cache_resource(show_spinner=False)
def _av_runtime(project_root: str) -> Path:
    data = base64.b85decode(_AV_BUNDLE)
    if hashlib.sha256(data).hexdigest() != _AV_ARCHIVE_SHA256:
        raise RuntimeError('AUTOVERSE 코드 파일이 손상되었습니다. main.py 원본을 다시 올려 주세요.')
    root = Path(tempfile.mkdtemp(prefix='autoverse-v3-'))
    with ZipFile(BytesIO(data)) as archive:
        archive.extractall(root)
    # Original vehicle data stays in the repository; no copy or overwrite.
    existing_data = Path(project_root) / 'data'
    if existing_data.is_dir():
        (root / 'data').symlink_to(existing_data, target_is_directory=True)
    return root

_AV_RUNTIME = _av_runtime(str(_AV_PROJECT_ROOT))
if str(_AV_RUNTIME) not in sys.path:
    sys.path.insert(0, str(_AV_RUNTIME))
runpy.run_path(str(_AV_RUNTIME / 'router.py'), run_name='__main__')
